/**
 * bot-assistant-tools 行 —— 助理档会话专用的两个跨会话工具：
 *   search_sessions：按标题/ID 子串搜宿主会话（deliver_message 的前置侦察）；
 *   deliver_message：向任意其他 DSH 会话投递一条用户消息（agents.get/resume + steer，
 *                    不等待回复、不创建会话、不改模型）。
 *
 * 挂载位置：只进 preset-assistant 的 plugins 列表（chat 档不受影响）。
 * 2026-11-27 用户定案：「都要」——加回旧助理行删掉的这两个工具。
 *
 * 跨行契约：只 import bot-bindings / bot-relay 的纯函数，宿主服务全走 ctx.get。
 */
import type { Context } from "./context-types.js";
import { resolveSessionRef, searchSessions } from "./bot-bindings.js";
import { buildUserMessage } from "./bot-relay.js";

export const name = "@bvbhu/as-one/bot-assistant-tools";
export const inject = ["agents", "tools"];

/** 宿主 agents 服务窄投影（只取本行用到的成员）。 */
interface AssistantToolsAgents {
	get?(sessionId: string): unknown;
	resume?(options: { resumeSessionId: string }): Promise<{ agent?: AgentLike }>;
}

/** agent 能力面。 */
interface AgentLike {
	steer?(message: unknown): unknown;
}

/** 工具注册表窄投影。 */
interface AssistantToolsRegistry {
	register(definition: unknown): () => void;
}

/** 工具输出渲染：统一渲染成一条文本块。 */
function renderText(value: unknown): unknown[] {
	return [{ type: "text", text: typeof value === "string" ? value : JSON.stringify(value) }];
}

export function apply(ctx: Context): void {
	const agents = (ctx as unknown as { agents?: AssistantToolsAgents }).agents;
	const tools = (ctx as unknown as { tools?: AssistantToolsRegistry }).tools;
	if (!tools || typeof tools.register !== "function") {
		ctx.logger?.warn?.("[as-one] tools service unavailable, bot-assistant-tools row skipped");
		return;
	}
	if (!agents || typeof agents.get !== "function") {
		ctx.logger?.warn?.("[as-one] agents service unavailable, bot-assistant-tools row skipped");
		return;
	}

	/** resume 出来的句柄缓存：会话是用户手工创建的，保持存活，不主动释放。 */
	const handles = new Map<string, { agent?: AgentLike }>();

	/** 取会话 agent：live 直接用；否则 resume 一次并缓存。 */
	const ensureAgent = async (sessionId: string): Promise<AgentLike | undefined> => {
		try {
			const live = agents.get?.(sessionId) as { agent?: AgentLike; steer?: unknown } | undefined;
			if (live && typeof live === "object") {
				const agent = live.agent ?? live;
				if (typeof agent?.steer === "function") return agent as AgentLike;
			}
		} catch {
			// get 抛错按未找到处理。
		}
		const cached = handles.get(sessionId);
		if (cached?.agent && typeof cached.agent.steer === "function") return cached.agent;
		if (typeof agents.resume !== "function") return undefined;
		try {
			const handle = await agents.resume({ resumeSessionId: sessionId });
			handles.set(sessionId, handle);
			return handle.agent;
		} catch (err) {
			ctx.logger?.warn?.(`[as-one] assistant-tools resume failed (${sessionId}):`, err);
			return undefined;
		}
	};

	ctx.effect(() => {
		const disposeSearch = tools.register({
			name: "search_sessions",
			description:
				"按标题或会话 ID 子串搜索宿主上的其他 DSH 会话，返回 id 与标题列表（最多 100 条）。"
				+ "投递消息前用它找到目标会话；空结果请换个更短的关键词。",
			parameters: {
				query: {
					type: "string",
					required: true,
					description: "会话标题或 ID 的子串（大小写不敏感）。",
				},
				limit: {
					type: "number",
					description: "最多返回条数，1–100，缺省 20。",
				},
			},
			output: { schema: { type: "string" }, render: renderText },
			async execute(args: { query?: unknown; limit?: unknown }) {
				const query = String(args?.query ?? "").trim();
				if (query === "") return "query 不能为空";
				const rawLimit = Number(args?.limit);
				const limit = Number.isFinite(rawLimit) && rawLimit > 0 ? Math.round(rawLimit) : 20;
				const hits = searchSessions(query, process.env, limit);
				if (hits.length === 0) return `没有匹配「${query}」的会话`;
				const lines = hits.map((hit) => `- ${hit.id}：${hit.title || "（无标题）"}`);
				return `${hits.length} 个匹配：\n${lines.join("\n")}`;
			},
		});

		const disposeDeliver = tools.register({
			name: "deliver_message",
			description:
				"向另一个 DSH 会话投递一条用户消息（会话 ID 或标题，支持前缀）。"
				+ "只投递不等待回复；目标会话需已存在且可恢复。投递成功返回确认文本。",
			parameters: {
				session: {
					type: "string",
					required: true,
					description: "目标会话 ID（可写唯一前缀）或标题。",
				},
				text: {
					type: "string",
					required: true,
					description: "要投递的用户消息正文。",
				},
			},
			output: { schema: { type: "string" }, render: renderText },
			async execute(args: { session?: unknown; text?: unknown }) {
				const ref = String(args?.session ?? "").trim();
				const text = String(args?.text ?? "").trim();
				if (ref === "" || text === "") return "session 与 text 都不能为空";
				const sessionId = resolveSessionRef(ref, process.env);
				if (sessionId === "") return `解析不到会话「${ref}」（先用 search_sessions 找）`;
				const agent = await ensureAgent(sessionId);
				if (!agent || typeof agent.steer !== "function") {
					return `会话 ${sessionId} 无法唤起（不存在或 resume 失败）`;
				}
				try {
					// 只投一次：steer 无返回值，绝不补 followup。
					agent.steer(buildUserMessage(text));
					return `已投递到会话 ${sessionId}`;
				} catch (err) {
					ctx.logger?.warn?.(`[as-one] assistant-tools steer failed (${sessionId}):`, err);
					return `投递失败：${(err as Error)?.message ?? err}`;
				}
			},
		});

		return () => {
			disposeSearch();
			disposeDeliver();
			handles.clear();
		};
	});
}
